    proposals.append({'id':f'M-S2-{n:02d}','severity':'P3','kind':'necessity / terminology','passage':actual,'before':before,'after':after,'deletion_test':reason,'necessary_content_retained':keep,'strongest_reading':'A short lead-in or specialist label can help when it adds a role or distinction. Here the immediately adjacent retained text already supplies that role, and the proposed change keeps the needed mathematics, assumptions and interpretation.','matching_typed_fields_to_update_if_any':fields or [],'status':'proposal only, not edited'})
